T=/dd/SYS/termcapecho "@@CASE@@compress-round-trip"/dd/CMDS/compress -c < $T > /dd/tmp/z.Z/dd/CMDS/compress -dc < /dd/tmp/z.Z > /dd/tmp/z.out/dd/CMDS/md5 /dd/tmp/z.outecho "@@CASE@@compress-really-compresses"/dd/CMDS/wc -c /dd/tmp/z.Zecho "@@CASE@@gzip-round-trip"/dd/CMDS/gzip -c < $T > /dd/tmp/g.gz/dd/CMDS/gzip -dc < /dd/tmp/g.gz > /dd/tmp/g.out/dd/CMDS/md5 /dd/tmp/g.outecho "@@CASE@@gzip-really-compresses"/dd/CMDS/wc -c /dd/tmp/g.gzecho "@@CASE@@gzip-reads-what-compress-wrote"/dd/CMDS/gzip -dc < /dd/tmp/z.Z > /dd/tmp/zg.out/dd/CMDS/md5 /dd/tmp/zg.outecho "@@CASE@@tar-round-trip"/dd/CMDS/cp $T /dd/tmp/tarme.txt/dd/CMDS/tar cf /dd/tmp/t.tar /dd/tmp/tarme.txt/dd/CMDS/rm /dd/tmp/tarme.txt/dd/CMDS/tar xf /dd/tmp/t.tar/dd/CMDS/md5 /dd/tmp/tarme.txtecho "@@CASE@@tar-lists-what-it-stored"/dd/CMDS/tar tvf /dd/tmp/t.tarecho "@@CASE@@zoo-adds-and-lists"/dd/CMDS/zoo a /dd/tmp/a.zoo $T/dd/CMDS/zoo l /dd/tmp/a.zooecho "@@CASE@@booz-reads-a-zoo"/dd/CMDS/booz -l /dd/tmp/a.zooecho "@@CASE@@zip-cannot-write-its-archive"/dd/CMDS/zip /dd/tmp/a.zip $Techo "@@CASE@@end"